const items = $input.all();

function gerarVariacao(numero) {
  let n = String(numero).replace(/\D/g, "");

  // padrão Brasil: 55 + DDD + número
  if (n.startsWith("55")) {
    const pais = n.slice(0, 2);
    const ddd = n.slice(2, 4);
    let resto = n.slice(4);

    // se tiver 9 na frente remove
    if (resto.startsWith("9")) {
      resto = resto.slice(1);
    } else {
      // se não tiver adiciona
      resto = "9" + resto;
    }

    return pais + ddd + resto;
  }

  return n;
}

const resultado = [];

for (const item of items) {
  const original = item.json.Telefone;
  const variacao = gerarVariacao(original);

  // item original
  resultado.push({
    json: {
      ...item.json,
      Telefone: String(original)
    }
  });

  // item duplicado com variação
  resultado.push({
    json: {
      ...item.json,
      Telefone: variacao
    }
  });
}

return resultado;

